WITH RECURSIVE PARAMS AS ( SELECT CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10)) ELSE NULL END AS DT_INI_IN, CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_FIM), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_FIM), 10)) ELSE NULL END AS DT_FIM_IN ), D AS ( SELECT LEAST(DT_INI, DT_FIM) AS DT_INI, GREATEST(DT_INI, DT_FIM) AS DT_FIM FROM ( SELECT COALESCE(DT_FIM_IN, CURDATE()) AS DT_FIM, COALESCE(DT_INI_IN, MAKEDATE(YEAR(COALESCE(DT_FIM_IN, CURDATE())), 1)) AS DT_INI FROM PARAMS ) X ), N12 AS ( SELECT 1 AS IDX UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 ), MESES AS ( SELECT N.IDX, DATE_FORMAT(DATE_SUB(DATE_FORMAT(D.DT_FIM, '%Y-%m-01'), INTERVAL (N.IDX - 1) MONTH), '%m/%Y') AS MES_LABEL, LEAST(LAST_DAY(DATE_SUB(DATE_FORMAT(D.DT_FIM, '%Y-%m-01'), INTERVAL (N.IDX - 1) MONTH)), D.DT_FIM) AS CORTE, CASE WHEN LAST_DAY(DATE_SUB(DATE_FORMAT(D.DT_FIM, '%Y-%m-01'), INTERVAL (N.IDX - 1) MONTH)) >= D.DT_INI THEN 1 ELSE 0 END AS ATIVO FROM N12 N CROSS JOIN D ), VINC AS ( SELECT DISTINCT c.ID_DET_DRE_TW, c.ID_CONTA_CONTABIL FROM CAD_CONTA_DRE_TW c ), BASE_BP AS ( SELECT per.MES_LABEL AS MES, b.CTACTB AS ID_CONTA_CONTABIL, SUM(CASE WHEN LEFT(b.CTACTB, 1) IN ('1', '2') THEN b.VLRLANC ELSE -b.VLRLANC END) AS VALOR FROM MESES per INNER JOIN IMP_BASE_BALANCETE b ON DATE(b.REFERENCIA) <= per.CORTE AND ( LEFT(b.CTACTB, 1) IN ('1', '2') OR YEAR(b.REFERENCIA) = YEAR(per.CORTE) ) WHERE per.ATIVO = 1 AND b.CODEMP = :VAR_EMPRESA_DRE GROUP BY per.MES_LABEL, b.CTACTB ), CALCULOS AS ( SELECT m.MES_LABEL AS MES, d.ID, d.ORDEM, d.DESCRICAO, d.TIPO, d.FORMATACAO, d.HIERARQUIA, d.ORDEM AS ORDEM_ORIGEM, COALESCE(SUM(t.VALOR), 0) AS VALOR FROM MESES m INNER JOIN DET_DRE_TW d ON d.ID_ESTR_DRE_TW = 5 AND d.TIPO = 'CONTA' LEFT JOIN VINC c ON c.ID_DET_DRE_TW = d.ID LEFT JOIN BASE_BP t ON t.ID_CONTA_CONTABIL = c.ID_CONTA_CONTABIL AND t.MES = m.MES_LABEL WHERE m.ATIVO = 1 GROUP BY m.MES_LABEL, d.ID, d.ORDEM, d.DESCRICAO, d.TIPO, d.FORMATACAO, d.HIERARQUIA UNION ALL SELECT c.MES, d.ID, d.ORDEM, d.DESCRICAO, d.TIPO, d.FORMATACAO, d.HIERARQUIA, c.ORDEM AS ORDEM_ORIGEM, c.VALOR * CASE WHEN LOCATE(CONCAT('-', '[', c.ORDEM, ']'), REPLACE(d.CALCULO, ' ', '')) > 0 THEN -1 ELSE 1 END AS VALOR FROM DET_DRE_TW d INNER JOIN CALCULOS c ON FIND_IN_SET( c.ORDEM, REPLACE(REPLACE(REPLACE(REPLACE(REPLACE( d.CALCULO, ' ', ''), '[', ''), ']', ''), '+', ','), '-', ',') ) WHERE d.TIPO = 'CALCULO' AND d.ID_ESTR_DRE_TW = 5 ), RESULTADOS AS ( SELECT MES, ORDEM, DESCRICAO, FORMATACAO, HIERARQUIA, SUM(VALOR) AS VALOR FROM CALCULOS GROUP BY MES, ORDEM, DESCRICAO, FORMATACAO, HIERARQUIA ), AGREGADOS AS ( SELECT MES, SUM(CASE WHEN ORDEM = 1 THEN VALOR END) AS V1, SUM(CASE WHEN ORDEM = 13 THEN VALOR END) AS V13, SUM(CASE WHEN ORDEM = 17 THEN VALOR END) AS V17, SUM(CASE WHEN ORDEM = 27 THEN VALOR END) AS V27, SUM(CASE WHEN ORDEM = 28 THEN VALOR END) AS V28, SUM(CASE WHEN ORDEM = 42 THEN VALOR END) AS V42 FROM RESULTADOS GROUP BY MES ), RESULTADOS_FINAIS AS ( SELECT * FROM RESULTADOS UNION ALL SELECT MES, 1001, 'LIQUIDEZ CORRENTE', NULL, '14.', COALESCE(V1, 0) / NULLIF(-COALESCE(V28, 0), 0) FROM AGREGADOS UNION ALL SELECT MES, 1002, 'LIQUIDEZ SECA', NULL, '15.', (COALESCE(V1, 0) - COALESCE(V13, 0)) / NULLIF(-COALESCE(V28, 0), 0) FROM AGREGADOS UNION ALL SELECT MES, 1003, 'LIQUIDEZ GERAL', NULL, '16.', (COALESCE(V1, 0) + COALESCE(V17, 0)) / NULLIF(-(COALESCE(V28, 0) + COALESCE(V42, 0)), 0) FROM AGREGADOS UNION ALL SELECT MES, 1004, 'SOLVÊNCIA GERAL', NULL, '17.', COALESCE(V27, 0) / NULLIF(-(COALESCE(V28, 0) + COALESCE(V42, 0)), 0) FROM AGREGADOS ) SELECT ORDEM, DESCRICAO, FORMATACAO, HIERARQUIA, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 12) THEN VALOR END) AS MES_12, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 11) THEN VALOR END) AS MES_11, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 10) THEN VALOR END) AS MES_10, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 9) THEN VALOR END) AS MES_09, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 8) THEN VALOR END) AS MES_08, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 7) THEN VALOR END) AS MES_07, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 6) THEN VALOR END) AS MES_06, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 5) THEN VALOR END) AS MES_05, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 4) THEN VALOR END) AS MES_04, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 3) THEN VALOR END) AS MES_03, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 2) THEN VALOR END) AS MES_02, MAX(CASE WHEN MES = (SELECT MES_LABEL FROM MESES WHERE IDX = 1) THEN VALOR END) AS MES_01, (SELECT DATE_FORMAT(DT_FIM, '%m/%Y') FROM D) AS MES_REF, (SELECT DT_INI FROM D) AS DATA_INICIO_USADA, (SELECT DT_FIM FROM D) AS DATA_FIM_USADA, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE) AS LANC_EMPRESA, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE AND DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D)) AS LANC_PERIODO, CASE WHEN (SELECT DT_INI_IN FROM PARAMS) IS NULL OR (SELECT DT_FIM_IN FROM PARAMS) IS NULL THEN 0 ELSE 1 END AS DATAS_OK FROM RESULTADOS_FINAIS GROUP BY ORDEM, DESCRICAO, FORMATACAO, HIERARQUIA ORDER BY ORDEM;